    const content = field('Observation / captured text', 'content', 'textarea', '', 'Record what is visible, along with limitations or context.');
    const file = field('Or import an evidence file', 'attachment', 'file', '', state.mode === 'browser' ? 'Browser mode keeps the file hash and metadata only. The original file stays on your device.' : 'Up to 4 MiB. The original bytes are captured in the local case by content hash.'); file.input.accept = '';
