    formDialog(attachmentFirst ? 'Import evidence' : 'Capture evidence', [title, kind, source, content, observed, file], async data => { const attachment = file.input.files?.[0]; if (attachment) { if (attachment.size > 4 * 1024 * 1024) throw new Error('Choose a file no larger than 4 MiB.'); const bytes = new Uint8Array(await attachment.arrayBuffer()); const payload = { name: attachment.name, media_type: attachment.type || 'application/octet-stream' }; if (state.mode === 'browser') Object.assign(payload, { sha256: await digest(bytes), bytes: attachment.size }); else { let binary = ''; for (let index = 0; index < bytes.length; index += 32768) binary += String.fromCharCode(...bytes.subarray(index, index + 32768)); payload.content_base64 = btoa(binary); } await store.action('/api/attachments', payload); toast('Evidence file imported'); }
      else { if (!String(data.get('title') || '').trim()) throw new Error('Give the evidence a title.'); await store.action('/api/evidence', { title: data.get('title'), kind: data.get('kind'), source_url: data.get('source_url'), content: data.get('content'), ...(data.get('observed_at') ? { observed_at: new Date(data.get('observed_at')).toISOString() } : {}) }); toast('Evidence captured'); } }, 'Save evidence');
