  function bind() { document.querySelectorAll('[data-icon]').forEach(node => node.append(icon(node.dataset.icon))); document.querySelector('#captureButton').addEventListener('click', () => evidenceModal()); document.querySelector('#collectButton').addEventListener('click', collectorModal); document.querySelector('#exportButton').addEventListener('click', exportCase); document.querySelector('#caseButton').addEventListener('click', caseModal); document.querySelector('#commandButton').addEventListener('click', commandPalette); document.querySelector('#keyboardButton').addEventListener('click', keyboardModal); document.querySelector('#modalClose').addEventListener('click', closeModal); document.querySelector('#mobileMenu').addEventListener('click', () => document.querySelector('.sidebar').classList.toggle('open')); document.querySelector('#modal').addEventListener('click', event => { if (event.target === event.currentTarget) { const rect = event.currentTarget.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeModal(); } }); window.addEventListener('hashchange', () => { const view = location.hash.slice(1); if (view !== state.view && NAV.some(row => row[0] === view)) { state.view = view; render(); } }); document.addEventListener('keydown', event => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); commandPalette(); return; } if (document.querySelector('#modal').open || /INPUT|TEXTAREA|SELECT/.test(event.target.tagName) || event.metaKey || event.ctrlKey || event.altKey) return; const action = { e: evidenceModal, n: noteModal, r: collectorModal, g: () => route('graph'), f: () => route('flows'), '?': keyboardModal }[event.key.toLowerCase()]; if (action) { event.preventDefault(); action(); } }); }
